"""V6-specific UI, without obsolete storage stations and dimensions."""
def prepare(d,structure,tabs,downloads):
    cards=''.join(f'<article class="card level-card"><h3>{l["label"]}</h3><p>Y {l["y"][0]}–{l["y"][1]} · {l["positions"]:,} Baupositionen</p><button class="mini" data-level-cut="{l["y"][1]}">Schnitt in 3D öffnen</button></article>' for l in d['structure']['levels'])
    structure='<section class="tab" id="tab-structure"><div class="page-intro"><h2>Version 6 · Euer gebauter Keller als Grundlage</h2><p>Schachbrettboden auf Y 95 und Außenwände bis Y 127 bleiben Grundlage. Untere Nebenräume, ein Großlager in voller Höhe und eine freie Porter-Galerie ersetzen die alten Kelleretagen.</p></div><div class="floor-grid">'+cards+'</div><div class="card"><h3>Gesamte Nordwand für eure Porter</h3><p>X −709…−659 · Z 767…780 · Boden Y 124. Vier Blöcke Raumhöhe über dem Boden; keine Möbel oder Schaltungen im Reservestreifen. Farbige Bodenlinien zeigen Chunkgrenzen. Perlenkammer, Auslöser und Verkabelung jedes Porters innerhalb eines passenden Chunks platzieren.</p><p>Die Vorlagen für eure bereits gebauten Porter sind nicht Bestandteil des Hausmodells. Auch die automatische Erkennung zählt den freien Ausbauplatz nicht als fertig gebaute Porterschaltung.</p></div><div class="card"><h3>Zugang und geheimer Abstieg</h3><p>Der südöstliche Leiterzugang bei X −661 / Z 803 verbindet Boden Y 95, Lager Y 102, Galerie Y 124 und EG Y 129. Eine zweite Leiter in der neuen Nische außerhalb der Westwand führt bei X −712 / Z 776 zum Gang auf Y 80. Drei Blöcke Kopfraum im unteren Gang sind freigehalten.</p><a href="umbau_v6.md" class="btn" download>Umbaufolge und Prüfgrenzen herunterladen</a></div></section>'
    system='<section class="tab" id="tab-system"><div class="page-intro"><h2>Großlager nach eurer Dustless-Litematic</h2><p>V6 verwendet ein integriertes Lager, nicht beide bisherigen Vorschlagsmodule. Die ursprüngliche Schaltungshöhe bleibt erhalten.</p></div><div class="card"><h3>Einbaukoordinaten</h3><p>Ursprung X −701 / Y 102 / Z 771 · keine Rotation. Gesamtausdehnung 27 × 22 × 27 Blöcke bis X −675 / Y 123 / Z 797. Vier Chunks: X −44/−43, Z 48/49.</p><p>Die vollständige Blockgeometrie und graue Glasverkleidung stehen im Atlas und in den Materialmengen. Die folgende V6-Litematic bewahrt zusätzlich die ursprünglichen Containerdaten und Entities. Das Haus-NBT enthält nur Blöcke; für Filterinventare und Golems die V6-Litematic verwenden. Material der Vorlage nicht nochmals zur Gesamtmaterialliste addieren.</p><div class="row"><button class="btn primary" id="v6OpenStorage">Lager im 3D-Modell</button><a class="btn" href="litematics/Blackthorn_V6_Dustless.litematic" download>V6-Lager mit Inventaren herunterladen</a></div></div><div class="card"><h3>Porter-Galerie · Nordwand vollständig frei</h3><p>51 × 14 Bodenpositionen. Die Technik jedes Porters muss in einer zusammenhängenden Chunkzone bleiben. Die breite westliche Randfläche kann als Wartungszugang dienen.</p><table><thead><tr><th>Zone</th><th>X-Bereich</th><th>Z-Bereich</th><th>Chunk</th></tr></thead><tbody><tr><td>West</td><td>−703…−690</td><td>769…780</td><td>−44 / 48</td></tr><tr><td>Mitte</td><td>−687…−674</td><td>769…780</td><td>−43 / 48</td></tr><tr><td>Ost</td><td>−671…−660</td><td>769…780</td><td>−42 / 48</td></tr></tbody></table><button class="btn" id="v6OpenNorth">Freie Nordwand im Plan ansehen</button></div><div class="notice"><p>Lager-Inbetriebnahme, Golem-Verhalten, Filterbelegung und Chunk-Laden sind im Spiel zu prüfen. Die Schaltung wurde nicht simuliert. Der zentrale Leiterzugang übernimmt Personenverkehr; eine neue automatische Itemverbindung ins EG ist nicht als betriebsbereit modelliert.</p></div></section>'
    tabs['material']=tabs['material'].replace('Einrichtung und originale Lager-Litematics haben separate Materiallisten.','Das integrierte V6-Lager ist bereits enthalten. Inventarinhalte und Entities sind keine zusätzlichen Baupositionen.')
    tabs['material']=tabs['material'].replace('Ausführlicher Prüfbericht</a>', 'Ausführlicher Prüfbericht</a> · <a href="materialbedarf_keller_zusaetzlich.csv" download>Zusatzmaterial Keller gegenüber eurem Bestand</a>')
    tabs['storage']=tabs['storage'].replace('50 Regallagerbuchten und sechs Privatreserven. Kategorien durchsuchen, Bestände notieren und die Position im Ebenenplan öffnen.','Fünf Reservefässer im unteren Keller. Notizen bleiben lokal; gemeinsame Materialmengen stehen unter Organisation → Gemeinsame Liste. Das automatisierte Großlager findet ihr unter Sortierung & Technik.').replace('lager_regale','v6_grosslager').replace('Regallager in 3D','Großlager in 3D')
    tabs['terrain']=tabs['terrain'].replace('<div class="earth-summary">','<div class="notice"><b>V6-Keller nach aktuellem Bestand</b><p>Die globale Höhenkarte beruht auf dem älteren Weltstand. Für euren Keller sind die aktuelle Umbau- und Freiraumliste maßgeblich.</p><a href="keller_umbau_6.0.csv" download>Keller-Umbau gegenüber Bestand</a> · <a href="freiraeume_6.0.csv" download>V6-Freiraumliste</a></div><div class="earth-summary">')
    structure=structure.replace('<div class="floor-grid">','<a class="outdoor-image" href="assets/keller_v6.png"><img src="assets/keller_v6.png" alt="Drei Kellerschnitte mit Chunkgrenzen und freier Nordwand" loading="lazy"></a><div class="floor-grid">')
    structure=structure.replace('<div class="floor-grid">','<div class="row"><button class="btn primary" data-cellar-floor>Vorhandenen Kellerboden in 3D ansehen</button><button class="btn" data-tab="plan">Ebenenplan öffnen</button></div><div class="notice"><p>In der Zielansicht wird die alte Geländehaut innerhalb des Kellers ausgespart. Die Ansicht „Historisches Originalgelände“ zeigt weiterhin den früheren Weltstand.</p></div><div class="floor-grid">')
    tabs['3d']=tabs['3d'].replace('>Originalgelände</option>','>Historisches Originalgelände</option>')
    structure=structure.replace('</section>', '<div class="card"><h3>Pool und Garten</h3><p>Ruhige Poolterrasse, breiter flacher Einstieg, Unterwasserlicht und Sitzplätze. Im Südgarten ergänzt eine offene Pergola die Rosenterrasse.</p><div class="row"><button class="btn" data-v6-outdoor="pool">Pool in 3D ansehen</button><button class="btn" data-v6-outdoor="garden">Südgarten in 3D ansehen</button><a class="btn" href="assets/aussen_v6.png">Außenanlagen im Blockplan</a><a class="btn" href="aussenanlagen_v6.md" download>Umbauhinweise für Pool und Garten</a></div></div></section>')
    structure=structure.replace('</section>','<div class="card"><h3>Wasserzugänge und Geheimsalon</h3><p>Zwei getrennte Zugänge verbinden Haus und Keller sowie Keller und tiefen Geheimgang. Jeweils links führt die Blasensäule nach oben, rechts der Fallschacht mit Wasserlandung nach unten. Hauszugang: X −669 / −667, Z 801. Tiefer Zugang: X −714 / −712, Z 779. Der bestehende Kellerboden auf Y 95 bleibt vollständig erhalten.</p><p>Der neue Geheimsalon am Gang besitzt 15 × 14 Blöcke Innenfläche und sieben Blöcke Raumhöhe. Bestehende Haupttreppe und Leiterzugänge bleiben vorhanden. Wasserstopp-Schilder und alle Säulen vor Nutzung im Spiel prüfen.</p><div class="row"><button class="btn" data-v6-water="house">Hauszugang in 3D</button><button class="btn" data-v6-water="secret">Tiefen Zugang in 3D</button><button class="btn" data-v6-water="room">Geheimsalon öffnen</button><a class="btn" href="wasserwege_v6.md" download>Bau- und Bedienhinweise</a></div></div></section>')
    categories=[('Bauen und Material',[('blockliste.csv','Alle Baupositionen'),('blackthorn_estate_6.0.nbt','Hausmodell V6 · NBT ohne Inventare'),('materialbedarf.csv','Gesamtmaterial inklusive Lager und Gelände'),('materialbedarf_haus.csv','Haus und Keller'),('materialbedarf_aussenanlagen.csv','Außenanlagen'),('materialbedarf_gelaende.csv','Gelände'),('materialpruefung.md','Materialprüfung')]),('Kellerumbau',[('umbau_v6.md','Umbaufolge und Grenzen'),('keller_umbau_6.0.csv','Änderungen gegenüber eurem Kellerbestand'),('materialbedarf_keller_zusaetzlich.csv','Zusatzmaterial im vermessenen Keller'),('freiraeume_6.0.csv','Freizuhaltende Positionen'),('litematics/Blackthorn_V6_Dustless.litematic','V6-Lager mit Inventaren und Entities'),('assets/keller_v6.png','Kellerschnitte mit Chunkraster'),('aenderungen_5.26_zu_6.0.csv','Modelländerungen 5.26 → V6')]),('Live und gemeinsames Bauen',[('downloads/BlackthornLive.jar','Paper-Plugin 1.3.0 mit V6-Plan'),('live_fortschritt.md','Live-Plugin installieren'),('gemeinsame_liste.md','Gemeinsame Materialliste einrichten')]),('Globales Gelände · älterer Weltstand',[('terraforming.csv','Globale Ist-/Soll-Spalten'),('terraforming_chunks.csv','Globale Chunk-Arbeiten'),('assets/terraforming_vergleich.png','Globaler Geländevergleich')])]
    downloads='<section class="tab" id="tab-downloads"><div class="page-intro"><h2>Version 6 · Dateien für euren Bau</h2><p>Das Großlager ist in den Gesamtmaterialmengen enthalten. Für den aktuellen Kellerbestand die V6-Umbau- und Zusatzmaterialliste verwenden. Globale Geländekarten beruhen weiterhin auf dem älteren Weltstand.</p></div><div class="download-grid">'+''.join('<article class="card"><h3>'+title+'</h3><ul class="file-list">'+''.join('<li><a href="'+file+'" download><span>'+label+'</span><small>'+file.rsplit('.',1)[-1].upper()+' ↓</small></a></li>' for file,label in files)+'</ul></article>' for title,files in categories)+'</div></section>'
    return structure,system,downloads
